"use client";

import { useEffect, useRef, useState, type ReactNode } from "react";
import {
  AnimatePresence,
  motion,
  useMotionTemplate,
  useMotionValue,
  useReducedMotion,
} from "framer-motion";

function MenuIcon({ className }: { className?: string }) {
  return (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden className={className}>
      <path d="M4 7h16M4 12h16M4 17h16" />
    </svg>
  );
}

function CloseIcon({ className }: { className?: string }) {
  return (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden className={className}>
      <path d="M18 6 6 18M6 6l12 12" />
    </svg>
  );
}

function ChevronIcon({ open }: { open: boolean }) {
  return (
    <motion.svg
      animate={{ rotate: open ? 180 : 0 }}
      transition={{ type: "spring", stiffness: 500, damping: 32 }}
      viewBox="0 0 24 24"
      width="13"
      height="13"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden
      className="text-slate-400"
    >
      <path d="m6 9 6 6 6-6" />
    </motion.svg>
  );
}

export interface RailNavPanelTile {
  title: string;
  description: string;
  icon: (props: { className?: string }) => ReactNode;
  href?: string;
}

export interface RailNavLink {
  id: string;
  label: string;
  href?: string;
  panel?: RailNavPanelTile[];
}

const COMPACT_BREAKPOINT = 560;

/**
 * A top nav bar whose collapse point is driven by its own rendered width via
 * ResizeObserver rather than a CSS breakpoint: drop it in a sidebar or a
 * split layout and it still switches to the mobile menu correctly. Hovering
 * a link with a `panel` drops a live preview strip beneath the bar, a
 * shared sliding pill tracks whichever link is hovered, and a soft glow
 * follows the pointer along the top edge.
 */
export function RailNav({
  links,
  activeId,
  brandLabel = "Nova",
  brandHref = "/",
  ctaLabel = "Sign in",
  ctaHref = "#",
}: {
  links: RailNavLink[];
  activeId?: string;
  brandLabel?: string;
  brandHref?: string;
  ctaLabel?: string;
  ctaHref?: string;
}) {
  const shouldReduceMotion = useReducedMotion();
  const rootRef = useRef<HTMLElement>(null);
  const closeTimer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);

  const [isCompact, setIsCompact] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const [hoveredId, setHoveredId] = useState<string | null>(null);
  const [openPanel, setOpenPanel] = useState<string | null>(null);
  const [mobileOpen, setMobileOpen] = useState(false);

  const beamX = useMotionValue(0);
  const beamOpacity = useMotionValue(0);
  const beamBackground = useMotionTemplate`radial-gradient(220px circle at ${beamX}px 0%, rgba(20,184,166,0.18), transparent 75%)`;

  useEffect(() => {
    const el = rootRef.current;
    if (!el) return;
    const observer = new ResizeObserver((entries) => {
      setIsCompact((entries[0]?.contentRect.width ?? 0) < COMPACT_BREAKPOINT);
    });
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  useEffect(() => {
    if (!isCompact) setMobileOpen(false);
  }, [isCompact]);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 8);
    onScroll();
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  const clearCloseTimer = () => {
    if (closeTimer.current) clearTimeout(closeTimer.current);
  };
  const scheduleClose = () => {
    clearCloseTimer();
    closeTimer.current = setTimeout(() => setOpenPanel(null), 150);
  };

  const handleMouseMove = (e: React.MouseEvent<HTMLElement>) => {
    if (shouldReduceMotion) return;
    const rect = rootRef.current?.getBoundingClientRect();
    if (!rect) return;
    beamX.set(e.clientX - rect.left);
  };

  return (
    <nav
      ref={rootRef}
      aria-label="Primary"
      onMouseMove={handleMouseMove}
      onMouseEnter={() => beamOpacity.set(1)}
      onMouseLeave={() => beamOpacity.set(0)}
      className={`sticky top-0 z-50 flex items-center justify-between gap-3 px-4 py-3.5 transition-colors duration-300 ${
        scrolled
          ? "border-b border-slate-200/80 bg-white/85 backdrop-blur-md dark:border-slate-800 dark:bg-neutral-950/85"
          : "border-b border-transparent bg-transparent"
      }`}
    >
      <motion.div aria-hidden className="pointer-events-none absolute inset-0" style={{ background: beamBackground, opacity: beamOpacity }} />

      <a href={brandHref} className="relative z-10 flex shrink-0 items-center gap-2 rounded-md focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-teal-500">
        <span aria-hidden className="flex h-6 w-6 items-center justify-center rounded-md bg-gradient-to-br from-teal-500 to-slate-900 dark:from-teal-400 dark:to-slate-700">
          <span className="h-2 w-2 rounded-sm bg-white/90" />
        </span>
        <span className="text-sm font-semibold tracking-tight text-slate-900 dark:text-white">{brandLabel}</span>
      </a>

      {!isCompact && (
        <div
          className="relative z-10 flex items-center gap-0.5"
          onMouseLeave={() => {
            setHoveredId(null);
            scheduleClose();
          }}
        >
          {links.map((link) => (
            <div key={link.id} className="relative">
              {link.panel ? (
                <button
                  type="button"
                  aria-haspopup="true"
                  aria-expanded={openPanel === link.id}
                  onMouseEnter={() => {
                    setHoveredId(link.id);
                    clearCloseTimer();
                    setOpenPanel(link.id);
                  }}
                  onFocus={() => {
                    setHoveredId(link.id);
                    clearCloseTimer();
                    setOpenPanel(link.id);
                  }}
                  onBlur={scheduleClose}
                  className="relative flex items-center gap-1 rounded-full px-3 py-1.5 text-sm font-medium text-slate-600 transition-colors hover:text-slate-900 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-teal-500 dark:text-slate-300 dark:hover:text-white"
                >
                  {hoveredId === link.id && (
                    <motion.span
                      layoutId="rail-hover-highlight"
                      className="absolute inset-0 -z-10 rounded-full bg-slate-100 dark:bg-white/[0.07]"
                      transition={shouldReduceMotion ? { duration: 0 } : { type: "spring", stiffness: 500, damping: 38 }}
                    />
                  )}
                  <span className="relative">{link.label}</span>
                  <ChevronIcon open={openPanel === link.id} />
                </button>
              ) : (
                <a
                  href={link.href ?? "#"}
                  aria-current={activeId === link.id ? "page" : undefined}
                  onMouseEnter={() => {
                    setHoveredId(link.id);
                    scheduleClose();
                  }}
                  onFocus={() => {
                    setHoveredId(link.id);
                    scheduleClose();
                  }}
                  className={`relative block rounded-full px-3 py-1.5 text-sm font-medium transition-colors focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-teal-500 ${
                    activeId === link.id
                      ? "font-semibold text-slate-900 dark:text-white"
                      : "text-slate-600 hover:text-slate-900 dark:text-slate-300 dark:hover:text-white"
                  }`}
                >
                  {hoveredId === link.id && (
                    <motion.span
                      layoutId="rail-hover-highlight"
                      className="absolute inset-0 -z-10 rounded-full bg-slate-100 dark:bg-white/[0.07]"
                      transition={shouldReduceMotion ? { duration: 0 } : { type: "spring", stiffness: 500, damping: 38 }}
                    />
                  )}
                  {link.label}
                  {activeId === link.id && (
                    <span aria-hidden className="absolute inset-x-3 -bottom-[3px] h-[2px] rounded-full bg-teal-500 dark:bg-teal-400" />
                  )}
                </a>
              )}
            </div>
          ))}
        </div>
      )}

      {!isCompact ? (
        <a
          href={ctaHref}
          className="relative z-10 shrink-0 rounded-full bg-slate-900 px-3.5 py-1.5 text-sm font-medium text-white transition-colors hover:bg-slate-700 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-teal-500 dark:bg-white dark:text-slate-900 dark:hover:bg-slate-200"
        >
          {ctaLabel}
        </a>
      ) : (
        <button
          type="button"
          aria-label={mobileOpen ? "Close menu" : "Open menu"}
          aria-expanded={mobileOpen}
          aria-controls="rail-nav-mobile-menu"
          onClick={() => setMobileOpen((v) => !v)}
          className="relative z-10 flex h-8 w-8 shrink-0 items-center justify-center rounded-md text-slate-600 transition-colors hover:bg-slate-100 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-teal-500 dark:text-slate-300 dark:hover:bg-white/10"
        >
          {mobileOpen ? <CloseIcon className="h-5 w-5" /> : <MenuIcon className="h-5 w-5" />}
        </button>
      )}

      <AnimatePresence>
        {!isCompact && openPanel && (
          <motion.div
            role="region"
            aria-label={`${links.find((l) => l.id === openPanel)?.label} preview`}
            initial={{ opacity: 0, y: -4 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -4 }}
            transition={shouldReduceMotion ? { duration: 0 } : { duration: 0.16, ease: [0.22, 1, 0.36, 1] }}
            onMouseEnter={clearCloseTimer}
            onMouseLeave={scheduleClose}
            className="absolute inset-x-0 top-full z-10 border-b border-slate-200/80 bg-white shadow-lg dark:border-slate-800 dark:bg-neutral-950"
          >
            <div className="grid grid-cols-3 gap-1 p-3">
              {links
                .find((l) => l.id === openPanel)
                ?.panel?.map((tile) => {
                  const Icon = tile.icon;
                  return (
                    <a
                      key={tile.title}
                      href={tile.href ?? "#"}
                      className="rounded-xl p-3 transition-colors hover:bg-slate-50 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-teal-500 dark:hover:bg-white/5"
                    >
                      <span className="flex h-8 w-8 items-center justify-center rounded-lg bg-teal-50 text-teal-600 dark:bg-teal-500/10 dark:text-teal-400">
                        <Icon className="h-4 w-4" />
                      </span>
                      <p className="mt-2 text-sm font-medium text-slate-700 dark:text-slate-200">{tile.title}</p>
                      <p className="mt-0.5 text-xs leading-relaxed text-slate-400 dark:text-slate-500">{tile.description}</p>
                    </a>
                  );
                })}
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {isCompact && mobileOpen && (
          <motion.div
            id="rail-nav-mobile-menu"
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: "auto" }}
            exit={{ opacity: 0, height: 0 }}
            transition={shouldReduceMotion ? { duration: 0 } : { height: { duration: 0.22, ease: [0.22, 1, 0.36, 1] }, opacity: { duration: 0.15 } }}
            className="absolute inset-x-0 top-full z-10 overflow-hidden border-b border-slate-200/80 bg-white shadow-lg dark:border-slate-800 dark:bg-neutral-950"
          >
            <ul className="flex flex-col gap-0.5 p-2">
              {links.map((link) => (
                <li key={link.id}>
                  <a
                    href={link.href ?? "#"}
                    aria-current={activeId === link.id ? "page" : undefined}
                    onClick={() => setMobileOpen(false)}
                    className={`block rounded-lg px-3 py-2.5 text-sm transition-colors focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-teal-500 ${
                      activeId === link.id
                        ? "bg-teal-50 font-semibold text-teal-700 dark:bg-teal-500/10 dark:text-teal-400"
                        : "font-medium text-slate-600 hover:bg-slate-50 dark:text-slate-300 dark:hover:bg-white/5"
                    }`}
                  >
                    {link.label}
                  </a>
                </li>
              ))}
              <li className="mt-1 border-t border-slate-100 pt-2 dark:border-slate-800">
                <a href={ctaHref} onClick={() => setMobileOpen(false)} className="block rounded-lg bg-slate-900 px-3 py-2.5 text-center text-sm font-medium text-white dark:bg-white dark:text-slate-900">
                  {ctaLabel}
                </a>
              </li>
            </ul>
          </motion.div>
        )}
      </AnimatePresence>
    </nav>
  );
}
